/**
 * Exo heat-3d driver: mirrors PolyBench/C heat-3d.c but calls the Exo-generated kernel.
 *
 * Original header:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* heat-3d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"

/* Include the Exo-generated kernel header. */
#include "generated/heat-3d/heat-3d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        A[i][j][k] = B[i][j][k] = (DATA_TYPE) (i + j + (n-k))* 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# 3D spatial tiling parameters (can be retuned per target).
# TI, TJ tile the slower-varying i/j dimensions; TK tiles the
# contiguous k dimension. Values chosen for good cache reuse.
TI = 16
TJ = 16
TK = 32

@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # Only interior points [1, n-1) are updated.
    assert n > 2

    for t in seq(0, tsteps):

        # --------------------------------------------------------------
        # Phase 1: update B from A using a 7-point stencil.
        # The interior [1, n-1)^3 is processed in cache-friendly tiles.
        # Tiles are enumerated by (I, J, K); within each tile we run
        # small fixed-size loops over (i, j, k), guarded to clip at
        # the true interior boundary.
        # --------------------------------------------------------------
        for I in seq(0, (n - 2 + TI - 1) / TI):
            for J in seq(0, (n - 2 + TJ - 1) / TJ):
                for K in seq(0, (n - 2 + TK - 1) / TK):
                    for i in seq(0, TI):
                        if 1 + I * TI + i < n - 1:
                            for j in seq(0, TJ):
                                if 1 + J * TJ + j < n - 1:
                                    for k in seq(0, TK):
                                        if 1 + K * TK + k < n - 1:
                                            # Global interior indices.
                                            Ai = 1 + I * TI + i
                                            Aj = 1 + J * TJ + j
                                            Ak = 1 + K * TK + k

                                            B[Ai, Aj, Ak] = (
                                                0.125 * (A[Ai + 1, Aj,     Ak    ] -
                                                         2.0 * A[Ai,     Aj,     Ak] +
                                                         A[Ai - 1, Aj,     Ak    ])
                                              + 0.125 * (A[Ai,     Aj + 1, Ak    ] -
                                                         2.0 * A[Ai,     Aj,     Ak] +
                                                         A[Ai,     Aj - 1, Ak    ])
                                              + 0.125 * (A[Ai,     Aj,     Ak + 1] -
                                                         2.0 * A[Ai,     Aj,     Ak] +
                                                         A[Ai,     Aj,     Ak - 1])
                                              + A[Ai, Aj, Ak]
                                            )

        # --------------------------------------------------------------
        # Phase 2: update A from B using the same stencil.
        # The tiling structure is identical, maximizing reuse of B tiles
        # in cache. A and B swap roles, but the arithmetic is unchanged.
        # --------------------------------------------------------------
        for I in seq(0, (n - 2 + TI - 1) / TI):
            for J in seq(0, (n - 2 + TJ - 1) / TJ):
                for K in seq(0, (n - 2 + TK - 1) / TK):
                    for i in seq(0, TI):
                        if 1 + I * TI + i < n - 1:
                            for j in seq(0, TJ):
                                if 1 + J * TJ + j < n - 1:
                                    for k in seq(0, TK):
                                        if 1 + K * TK + k < n - 1:
                                            Ai = 1 + I * TI + i
                                            Aj = 1 + J * TJ + j
                                            Ak = 1 + K * TK + k

                                            A[Ai, Aj, Ak] = (
                                                0.125 * (B[Ai + 1, Aj,     Ak    ] -
                                                         2.0 * B[Ai,     Aj,     Ak] +
                                                         B[Ai - 1, Aj,     Ak    ])
                                              + 0.125 * (B[Ai,     Aj + 1, Ak    ] -
                                                         2.0 * B[Ai,     Aj,     Ak] +
                                                         B[Ai,     Aj - 1, Ak    ])
                                              + 0.125 * (B[Ai,     Aj,     Ak + 1] -
                                                         2.0 * B[Ai,     Aj,     Ak] +
                                                         B[Ai,     Aj,     Ak - 1])
                                              + B[Ai, Aj, Ak]
                                            )

# -------------------------------------------------------------------
# Scheduling:
#   - Parallelize the outer tile loops in both phases over I (i-tiles).
#     This exploits multi-core parallelism while preserving the strict
#     time-stepping order and the barrier between B<-A and A<-B.
# -------------------------------------------------------------------
kernel_heat_3d = parallelize_loop(kernel_heat_3d, "I")
kernel_heat_3d = parallelize_loop(kernel_heat_3d, "I #1")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 3D views to 1D pointers. */
  kernel_heat_3d(/*ctxt=*/NULL, tsteps, n,
                 (DATA_TYPE*)POLYBENCH_ARRAY(A),
                 (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
